VOWELS = "aeiou"


def translate(text):
    return " ".join(translate_word(word) for word in text.split())


def translate_word(word):
    # Rule 1: starts with a vowel, or with "xr" or "yt"
    if word[0] in VOWELS or word[:2] in ("xr", "yt"):
        return word + "ay"

    # Find where the consonant cluster ends: the first vowel,
    # or the first "y" (treated as a vowel only when not leading).
    split = len(word)
    for i, ch in enumerate(word):
        if ch in VOWELS or (ch == "y" and i > 0):
            split = i
            break

    # Rule 3: if the cluster ends in "qu", move the "qu" along with it
    if word[split:split + 2] == "qu":
        split += 2

    return word[split:] + word[:split] + "ay"

